    // LIFECYCLE METHODS
    protected override async Task OnInitializedAsync()
    {
        await LoadInitialData();
    }

    private async Task LoadInitialData()
    {
        isLoading = true;
        StateHasChanged();

        try
        {
            // Lấy mã trường từ Local Storage
            maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
            selectedTenCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevelText");
            var rawNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
            // rawNamHoc có dạng "2025-2026" → lấy phần tử đầu tiên
            if (!string.IsNullOrEmpty(rawNamHoc))
                selectedNamHoc = rawNamHoc.Split('-')[0].Trim();
            
            if (string.IsNullOrEmpty(maTruongBo))
            {
                await JS.InvokeVoidAsync("alert", "Không tìm thấy mã trường. Vui lòng đăng nhập lại.");
                Nav.NavigateTo("/");
                return;
            }

            // Lấy cấp học từ Local Storage
            await LoadLevelFromStorage();

            // Khởi tạo danh sách tab
            InitializeSyncTabs();

            // Load tất cả dữ liệu song song
            await LoadAllDataParallel();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi khi tải dữ liệu: {ex.Message}");
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    private async Task LoadLevelFromStorage()
    {
        try
        {
            var capHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
            var tenCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevelText");

            if (!string.IsNullOrEmpty(capHoc))
            {
                selectedCapHoc = capHoc;
                selectedTenCapHoc = tenCapHoc ?? "Cấp Tiểu học";
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi khi đọc cấp học: {ex.Message}");
        }
    }

    private void InitializeSyncTabs()
    {
        syncTabs = new List<SyncTabInfo>
        {
            new SyncTabInfo { Id = 1, Title = "1. Danh sách lớp học",    Count = "0" },
            new SyncTabInfo { Id = 2, Title = "2. Danh sách học sinh",    Count = "0" },
            new SyncTabInfo { Id = 3, Title = "3. Danh sách giáo viên",  Count = "0" },
            new SyncTabInfo { Id = 4, Title = "4. Phân công GD & CN",     Count = "0" }
        };
    }

    // DATA LOADING METHODS
    private async Task LoadAllDataParallel()
    {
        if (string.IsNullOrEmpty(maTruongBo)) return;

        isTabLoading = true;
        StateHasChanged();

        try
        {
            var namHocFull = $"{selectedNamHoc}-{int.Parse(selectedNamHoc) + 1}";

            // Build lopDict trước (cần thiết cho phân công)
            var lopTask       = TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, namHocFull);
            var hsTask        = TruongService.hGetDanhSachHocSinh(maTruongBo, selectedCapHoc, namHocFull);
            var gvTask        = TruongService.hGetDanhSachGiaoVien(maTruongBo, namHocFull);

            await Task.WhenAll(lopTask, hsTask, gvTask);

            lopHocs   = lopTask.Result;
            hocSinhs  = hsTask.Result;
            giaoViens = gvTask.Result;

            // Phân công cần lopDict
            var lopDict = lopHocs
                .Where(l => l.IdLopBo > 0)
                .ToDictionary(l => l.IdLopBo,
                              l => (TenLop: l.TenLop ?? "", MaKhoiBo: (l.MaKhoiBo ?? "").PadLeft(2, '0')));

            var cnTask = TruongService.hGetDanhSachPhanCongChuNhiem(maTruongBo, namHocFull, lopDict);
            var gdTask = TruongService.hGetDanhSachPhanCongGiangDay(maTruongBo, namHocFull, null, lopDict);
            await Task.WhenAll(cnTask, gdTask);

            phanCongChuNhiems = cnTask.Result;
            phanCongGiangDays = gdTask.Result;

            // Cập nhật count cho các tab
            UpdateTabCount(1, lopHocs.Count.ToString());
            UpdateTabCount(2, hocSinhs.Count.ToString());
            UpdateTabCount(3, giaoViens.Count.ToString());
            UpdateTabCount(4, $"{phanCongChuNhiems.Count} CN / {phanCongGiangDays.Count} GD");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi khi tải dữ liệu song song: {ex.Message}");
        }
        finally
        {
            isTabLoading = false;
            StateHasChanged();
        }
    }

    private async Task LoadDataForCurrentTab()
    {
        if (string.IsNullOrEmpty(maTruongBo)) return;

        isTabLoading = true;
        currentPage = 1;
        StateHasChanged();
        var namHocFull = $"{selectedNamHoc}-{int.Parse(selectedNamHoc) + 1}";

        try
        {
            if (activeTab == 1) // Lớp học
            {
                lopHocs = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, namHocFull);
                // Đồng thời tải phân công GVCN để hiển thị cột GV chủ nhiệm
                if (!phanCongChuNhiems.Any())
                    phanCongChuNhiems = await TruongService.hGetDanhSachPhanCongChuNhiem(maTruongBo, namHocFull);
                // Đồng thời tải học sinh để hiển thị sĩ số
                if (!hocSinhs.Any())
                    hocSinhs = await TruongService.hGetDanhSachHocSinh(maTruongBo, selectedCapHoc, namHocFull);
                UpdateTabCount(1, lopHocs.Count.ToString());
            }
            else if (activeTab == 2) // Học sinh
            {
                hocSinhs = await TruongService.hGetDanhSachHocSinh(maTruongBo, selectedCapHoc, namHocFull);
                if (!lopHocs.Any())
                    lopHocs = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, namHocFull);
                UpdateTabCount(2, hocSinhs.Count.ToString());
            }
            else if (activeTab == 3) // Giáo viên
            {
                giaoViens = await TruongService.hGetDanhSachGiaoVien(maTruongBo, namHocFull);
                UpdateTabCount(3, giaoViens.Count.ToString());
            }
            else if (activeTab == 4) // Phân công
            {
                // Build dict lớp và khối để join
                if (!lopHocs.Any())
                    lopHocs = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, namHocFull);
                var lopDict = lopHocs
                    .Where(l => l.IdLopBo > 0)
                    .ToDictionary(l => l.IdLopBo,
                                  l => (TenLop: l.TenLop ?? "", MaKhoiBo: (l.MaKhoiBo ?? "").PadLeft(2, '0')));

                phanCongChuNhiems = await TruongService.hGetDanhSachPhanCongChuNhiem(
                    maTruongBo, namHocFull, lopDict);   
                phanCongGiangDays = await TruongService.hGetDanhSachPhanCongGiangDay(
                    maTruongBo, namHocFull, null, lopDict);
                UpdateTabCount(4, $"{phanCongChuNhiems.Count} CN / {phanCongGiangDays.Count} GD");
            }
            StateHasChanged();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi khi tải dữ liệu tab {activeTab}: {ex.Message}");
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
        finally
        {
            isTabLoading = false;
            StateHasChanged();
        }
    }

    // SYNC METHODS
    private async Task SyncAllData()
    {
        await StartSyncProcess(true);
    }

    private async Task SyncCurrentTab()
    {
        await StartSyncProcess(false);
    }

    private async Task StartSyncProcess(bool syncAll)
    {
        _lastSyncAll   = syncAll;
        isSyncing      = true;
        showSyncModal  = true;
        syncCompleted  = false;
        syncError      = false;
        overallProgress = 0;
        syncTotalFormatted = "";

        InitializeSyncSteps(syncAll);
        StateHasChanged();

        var sw = System.Diagnostics.Stopwatch.StartNew();

        try
        {
            var namHocInt    = int.Parse(selectedNamHoc);
            var visibleSteps = syncSteps.Where(s => s.IsVisible).ToList();
            int totalSteps   = visibleSteps.Count;
            // int[] dùng thay cho ref int vì async method không hỗ trợ ref param
            var doneSteps = new int[] { 0 };

            // Helper cập nhật overall progress
            void UpdateOverall()
            {
                if (totalSteps == 0) return;
                var active = syncSteps.FirstOrDefault(s => s.Status == "active");
                double done = doneSteps[0] * 100.0;
                double cur  = active?.Progress ?? 0;
                overallProgress = (int)((done + cur) / totalSteps);
                StateHasChanged();
            }

            if (syncAll || activeTab == 1)
                await SyncStepAsync("lop",         () => SyncLopHocAsync(namHocInt),           doneSteps, UpdateOverall);

            if (syncAll || activeTab == 2)
                await SyncStepAsync("hocsinh",     () => SyncHocSinhAsync(namHocInt),          doneSteps, UpdateOverall);

            if (syncAll || activeTab == 3)
                await SyncStepAsync("giaovien",    () => SyncGiaoVienAsync(namHocInt),         doneSteps, UpdateOverall);

            if (syncAll || activeTab == 4)
                await SyncStepAsync("phancong_cn", () => SyncPhanCongChuNhiemAsync(namHocInt), doneSteps, UpdateOverall);

            if (syncAll || activeTab == 4)
                await SyncStepAsync("phancong_gd", () => SyncPhanCongGiangDayAsync(namHocInt), doneSteps, UpdateOverall);

            overallProgress    = 100;
            syncCompleted      = true;
            syncTotalFormatted = $"{sw.Elapsed.TotalSeconds:0.0}s — " +
                                 $"{syncSteps.Sum(s => s.Added)} bản ghi mới, " +
                                 $"{syncSteps.Sum(s => s.Updated)} cập nhật";
            UpdateSyncTimes();
            await LoadDataForCurrentTab();
        }
        catch (Exception ex)
        {
            syncError = true;
            Console.WriteLine($"Lỗi đồng bộ: {ex.Message}");
        }
        finally
        {
            isSyncing = false;
            StateHasChanged();
        }
    }

    private void InitializeSyncSteps(bool syncAll)
    {
        syncSteps.Clear();

        if (syncAll)
        {
            syncSteps.Add(new SyncStep { Key = "lop",         Title = "Đồng bộ lớp học",      Status = "pending" });
            syncSteps.Add(new SyncStep { Key = "hocsinh",     Title = "Đồng bộ học sinh",     Status = "pending" });
            syncSteps.Add(new SyncStep { Key = "giaovien",    Title = "Đồng bộ giáo viên",    Status = "pending" });
            syncSteps.Add(new SyncStep { Key = "phancong_cn", Title = "Phân công chủ nhiệm",  Status = "pending" });
            syncSteps.Add(new SyncStep { Key = "phancong_gd", Title = "Phân công giảng dạy",  Status = "pending" });
        }
        else
        {
            if (activeTab == 4)
            {
                syncSteps.Add(new SyncStep { Key = "phancong_cn", Title = "Phân công chủ nhiệm", Status = "pending" });
                syncSteps.Add(new SyncStep { Key = "phancong_gd", Title = "Phân công giảng dạy", Status = "pending" });
            }
            else
            {
                var step = activeTab switch
                {
                    1 => new SyncStep { Key = "lop",      Title = "Đồng bộ lớp học" },
                    2 => new SyncStep { Key = "hocsinh",  Title = "Đồng bộ học sinh" },
                    3 => new SyncStep { Key = "giaovien", Title = "Đồng bộ giáo viên" },
                    _ => new SyncStep { Key = "all",      Title = "Đồng bộ dữ liệu" }
                };
                step.Status = "pending";
                syncSteps.Add(step);
            }
        }
    }

    /// <summary>
    /// Thực thi 1 bước đồng bộ với progress bar thực tế + đếm record + đo thời gian.
    /// </summary>
    private async Task SyncStepAsync(
        string stepKey,
        Func<Task> syncAction,
        int[] doneSteps,        // dùng int[] thay ref int vì async không hỗ trợ ref param
        Action updateOverall)
    {
        var step = syncSteps.FirstOrDefault(s =>
            s.Key.Equals(stepKey, StringComparison.OrdinalIgnoreCase));
        if (step == null) return;

        var sw = System.Diagnostics.Stopwatch.StartNew();

        try
        {
            step.Status   = "active";
            step.Progress = 0;
            step.Message  = "Đang kết nối...";
            step.Added    = 0;
            step.Updated  = 0;
            step.Skipped  = 0;
            StateHasChanged();

            // Animate progress 0 → 30 trước khi gọi API (giả lập kết nối)
            for (int p = 0; p <= 30; p += 10)
            {
                step.Progress = p;
                step.Message  = p == 0 ? "Đang kết nối..." : "Đang tải dữ liệu từ SGD...";
                updateOverall();
                await Task.Delay(80);
            }

            // ── Gọi API thực ──
            step.Message = "Đang đồng bộ...";
            await syncAction.Invoke();

            // Animate 30 → 100
            for (int p = 40; p <= 100; p += 10)
            {
                step.Progress = p;
                step.Message  = p < 100 ? "Đang ghi dữ liệu..." : "Hoàn tất";
                updateOverall();
                await Task.Delay(40);
            }

            sw.Stop();
            step.ElapsedMs = sw.ElapsedMilliseconds;
            step.Progress  = 100;
            step.Status    = "completed";
            step.Message   = "Hoàn tất";
        }
        catch (Exception ex)
        {
            sw.Stop();
            step.ElapsedMs   = sw.ElapsedMilliseconds;
            step.Status      = "failed";
            step.Message     = "Thất bại";
            step.ErrorDetail = ex.Message;
            throw;
        }
        finally
        {
            doneSteps[0]++;
            updateOverall();
            StateHasChanged();
        }
    }


