    private async Task<SyncResponseDto> PostSyncRequestAsync(string apiUrl, object request)
    {
        var response = await Http.PostAsJsonAsync(apiUrl, request);
        var content = await response.Content.ReadAsStringAsync();

        if (string.IsNullOrWhiteSpace(content))
        {
            return new SyncResponseDto
            {
                Status = (int)response.StatusCode,
                Message = response.IsSuccessStatusCode ? "Đồng bộ hoàn tất" : $"Lỗi đồng bộ: {response.StatusCode}"
            };
        }

        try
        {
            var dto = JsonSerializer.Deserialize<SyncResponseDto>(content, new JsonSerializerOptions
            {
                PropertyNameCaseInsensitive = true
            });

            if (dto != null)
            {
                dto.Status = dto.Status == 0 ? (int)response.StatusCode : dto.Status;
                return dto;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Không thể parse phản hồi đồng bộ: {ex.Message}");
        }

        return new SyncResponseDto
        {
            Status = (int)response.StatusCode,
            Message = response.IsSuccessStatusCode ? content : $"Lỗi đồng bộ: {response.StatusCode}"
        };
    }

    private void HandleSyncResult(SyncResponseDto result, string syncName)
    {
        var status = result.Status;
        var message = (result.Message ?? string.Empty).Trim();

        if (status == 404 || message.Contains("Phiên đăng nhập quá hạn", StringComparison.OrdinalIgnoreCase))
        {
            throw new Exception("Phiên đăng nhập quá hạn, vui lòng đăng nhập lại");
        }

        if (status == 200)
        {
            var normalizedMessage = NormalizeSuccessMessage(message);

            if (!string.IsNullOrEmpty(normalizedMessage))
            {
                syncTotalFormatted = normalizedMessage;
            }

            if (message.Contains("Đã tồn tại", StringComparison.OrdinalIgnoreCase) ||
                message.Contains("không có dòng mới để thêm", StringComparison.OrdinalIgnoreCase))
            {
                var step = syncSteps.FirstOrDefault(s => s.Status == "active" && s.Message != null);
                if (step != null)
                {
                    step.Skipped = Math.Max(step.Skipped, 1);
                }
            }

            return;
        }

        if (status >= 400)
        {
            throw new Exception(string.IsNullOrWhiteSpace(message)
                ? $"Lỗi đồng bộ {syncName}: {status}"
                : message);
        }

        throw new Exception(string.IsNullOrWhiteSpace(message)
            ? $"Lỗi đồng bộ {syncName}"
            : message);
    }

    private string NormalizeSuccessMessage(string message)
    {
        if (string.IsNullOrWhiteSpace(message))
        {
            return "Đồng bộ dữ liệu thành công";
        }

        if (message.Contains("Dữ liệu đã tồn tại", StringComparison.OrdinalIgnoreCase) ||
            message.Contains("không có dòng mới để thêm", StringComparison.OrdinalIgnoreCase))
        {
            return "Dữ liệu đã tồn tại, không có dòng mới để thêm";
        }

        if (message.Contains("Đồng bộ dữ liệu thành công", StringComparison.OrdinalIgnoreCase))
        {
            return "Đồng bộ dữ liệu thành công";
        }

        return message;
    }

    public class SyncResponseDto
    {
        public int Status { get; set; }
        public string Message { get; set; } = "";
        public JsonElement? Data { get; set; }
    }

    // HELPER METHODS
    private void UpdateTabCount(int tabId, string count)
    {
        var tab = syncTabs.FirstOrDefault(t => t.Id == tabId);
        if (tab != null)
        {
            tab.Count = count;
            tab.LastSyncTime = DateTime.Now;
        }
    }
    
    private void UpdateSyncTimes()
    {
        foreach (var tab in syncTabs)
        {
            tab.LastSyncTime = DateTime.Now;
        }
    }
    
    private string GetTabCount(int tabId)
    {
        return tabId switch
        {
            1 => lopHocs.Count.ToString(),
            2 => hocSinhs.Count.ToString(),
            3 => giaoViens.Count.ToString(),
            4 => $"{phanCongChuNhiems.Count} CN / {phanCongGiangDays.Count} GD",
            _ => "0"
        };
    }
    
