    private async Task SwitchTab(int tabId)
    {
        if (activeTab == tabId) return; // không load lại nếu đang ở tab đó rồi
        activeTab = tabId;
        currentPage = 1;
        subTab = 1;
        StateHasChanged();
    }
    
    private void OnPageChanged(int page)
    {
        currentPage = page;
        StateHasChanged();
    }

    private void OnPageSizeChanged(int size)
    {
        pageSize = size;
        currentPage = 1;
        StateHasChanged();
    }

    private void ChangePage(int newPage)
    {
        if (newPage >= 1 && newPage <= TotalPages)
        {
            currentPage = newPage;
            StateHasChanged();
        }
    }

