    {
        selectedTenCapHoc = selectedCapHoc switch
        {
            "02" => "Cấp Tiểu học",
            "03" => "Cấp THCS",
            "04" => "Cấp THPT",
            _ => "Cấp Tiểu học"
        };

        await LoadDataForCurrentTab();
    }

    private void CloseSyncModal()
    {
        showSyncModal = false;
        syncCompleted = false;
        syncError = false;
        StateHasChanged();
    }

